  ['mercury', 0.2408467],
  ['venus', 0.61519726],
  ['earth', 1.0],
  ['mars', 1.8808158],
  ['jupiter', 11.862615],
  ['saturn', 29.447498],
  ['uranus', 84.016846],
  ['neptune', 164.79132],
]);

export const age = (planet, seconds) => {
  const orbitalPeriod = ORBITAL_PERIODS.get(planet);

  if (orbitalPeriod === undefined) {
    throw new Error(`Unknown planet: ${planet}`);
  }

  const earthYears = seconds / EARTH_YEAR_IN_SECONDS;
  const planetYears = earthYears / orbitalPeriod;

  // Round to two decimal places.
  return Math.round(planetYears * 100) / 100;
};
