pub struct Error;

pub struct Scale {
    notes: Vec<String>,
}

const SHARP_NOTES: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

const FLAT_NOTES: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

/// Returns true if the tonic is spelled with flats (or is a flat-key tonic).
fn uses_flats(tonic: &str) -> bool {
    matches!(
        tonic,
        "F" | "Bb" | "Eb" | "Ab" | "Db" | "Gb" | "d" | "g" | "c" | "f" | "bb" | "eb"
    )
}

/// Parses a note name (case-insensitive letter, optional '#' or 'b') into a
/// semitone index in 0..12, where 0 is A.
fn note_index(name: &str) -> Option<usize> {
    let mut chars = name.chars();
    let letter = chars.next()?.to_ascii_uppercase();
    let base: i32 = match letter {
        'A' => 0,
        'B' => 2,
        'C' => 3,
        'D' => 5,
        'E' => 7,
        'F' => 8,
        'G' => 10,
        _ => return None,
    };
    let mut offset = 0;
    for c in chars {
        match c {
            '#' => offset += 1,
            'b' => offset -= 1,
            _ => return None,
        }
    }
    Some((base + offset).rem_euclid(12) as usize)
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let start = note_index(tonic).ok_or(Error)?;
        let table = if uses_flats(tonic) {
            &FLAT_NOTES
        } else {
            &SHARP_NOTES
        };

        let mut notes = Vec::with_capacity(intervals.len() + 1);
        let mut current = start;
        notes.push(table[current].to_string());

        for step in intervals.chars() {
            let semitones = match step {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
            };
            current = (current + semitones) % 12;
            notes.push(table[current].to_string());
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
