use std::fmt;

/// Errors that can occur when constructing a scale.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Error {
    /// The tonic is not a valid note name such as `C`, `f#`, or `Bb`.
    InvalidTonic(String),
    /// The interval pattern contains a character other than `m`, `M`, or `A`.
    InvalidInterval(char),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Error::InvalidTonic(tonic) => write!(f, "invalid tonic: {tonic}"),
            Error::InvalidInterval(c) => write!(f, "invalid interval: {c}"),
        }
    }
}

impl std::error::Error for Error {}

/// Note names spelled with sharps, indexed by semitones above C.
const SHARP_NAMES: [&str; 12] = ["C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"];

/// Note names spelled with flats, indexed by semitones above C.
const FLAT_NAMES: [&str; 12] = ["C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"];

/// Tonics whose scales are spelled with flats.
/// Case matters: `d` is D minor, while `D` is D major.
const FLAT_TONICS: [&str; 13] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", // major
    "d", "g", "c", "f", "bb", "eb", "ab", // minor
];

#[derive(Debug)]
pub struct Scale {
    notes: Vec<String>,
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let mut pitch = parse_tonic(tonic)?;
        let steps = parse_intervals(intervals)?;

        let names = if FLAT_TONICS.contains(&tonic) {
            &FLAT_NAMES
        } else {
            &SHARP_NAMES
        };

        let mut notes = Vec::with_capacity(steps.len());
        for step in steps {
            notes.push(names[pitch].to_string());
            pitch = (pitch + step) % 12;
        }

        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}

/// Converts a tonic such as `C`, `f#`, or `Bb` into a pitch class (0 = C, 11 = B).
fn parse_tonic(tonic: &str) -> Result<usize, Error> {
    let invalid = || Error::InvalidTonic(tonic.to_string());
    let mut chars = tonic.chars();

    let base: i32 = match chars.next().map(|c| c.to_ascii_uppercase()) {
        Some('C') => 0,
        Some('D') => 2,
        Some('E') => 4,
        Some('F') => 5,
        Some('G') => 7,
        Some('A') => 9,
        Some('B') => 11,
        _ => return Err(invalid()),
    };

    let accidental: i32 = match chars.next() {
        None => 0,
        Some('#') => 1,
        Some('b') => -1,
        Some(_) => return Err(invalid()),
    };

    if chars.next().is_some() {
        return Err(invalid());
    }

    Ok((base + accidental).rem_euclid(12) as usize)
}

/// Converts an interval pattern into semitone steps: `m` = 1, `M` = 2, `A` = 3.
fn parse_intervals(intervals: &str) -> Result<Vec<usize>, Error> {
    intervals
        .chars()
        .map(|c| match c {
            'm' => Ok(1),
            'M' => Ok(2),
            'A' => Ok(3),
            other => Err(Error::InvalidInterval(other)),
        })
        .collect()
}
```

I'll implement the scale generation. The approach:

- Represent the chromatic scale with sharps and flats, choosing the spelling (sharps or flats) based on the tonic and the major/minor key rules from the instructions. Chromatic scales use sharps by default unless the tonic is a flat key (F, Bb, Eb, Ab, Db, Gb, and their minor counterparts such as d, g, c, f, bb, eb).
- Parse the interval string where `m` = half step (1), `M` = whole step (2), and `A` = augmented second (3). The interval string is a sequence of characters, one per step.
- `Scale::new` builds the scale by walking the intervals from the tonic. `Scale::chromatic` uses twelve half-step intervals.
- `enumerate` returns the notes of the scale, where the final note wraps back to the tonic only when the intervals complete an octave (the result includes all notes generated by the intervals, which is the standard exercism behavior).

Note on the interval string: in the Exercism spec, `intervals` is a string like `"MMmMMMm"`, where each character is one step: `m` = 1 semitone, `M` = 2 semitones, `A` = 3 semitones.

