fn find_tonic(tonic: &str) -> Result<(usize, bool), Error> {
    // Try the spelling that matches the key signature first, then the other.
    let flats = uses_flats(tonic);
    let primary = if flats { &FLAT_NOTES } else { &SHARP_NOTES };
    let secondary = if flats { &SHARP_NOTES } else { &FLAT_NOTES };

    if let Some(idx) = note_index(tonic, primary) {
        return Ok((idx, flats));
    }
    if let Some(idx) = note_index(tonic, secondary) {
        return Ok((idx, !flats));
    }
    Err(Error)
}

