#[derive(Debug)]
pub struct Error;

/// Note names (indexed by semitone, A = 0) using sharps.
const SHARP_NAMES: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

/// Note names (indexed by semitone, A = 0) using flats.
const FLAT_NAMES: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

/// Tonics whose scales are written with flats (major keys are uppercase,
/// minor keys are lowercase).
const FLAT_TONICS: [&str; 12] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb",
];

pub struct Scale {
    start: usize,
    intervals: Vec<usize>,
    use_flats: bool,
}

/// Parses a tonic such as "C", "f#", "Bb" or "bb" into a semitone index
/// (A = 0) and whether it carries a flat accidental.
fn parse_tonic(tonic: &str) -> Result<(usize, bool), Error> {
    let mut chars = tonic.chars();
    let letter = chars.next().ok_or(Error)?.to_ascii_uppercase();
    let base: i32 = match letter {
        'A' => 0,
        'B' => 2,
        'C' => 3,
        'D' => 5,
        'E' => 7,
        'F' => 8,
        'G' => 10,
        _ => return Err(Error),
    };
    let rest: String = chars.collect();
    let (offset, flat) = match rest.as_str() {
        "" => (0, false),
        "#" => (1, false),
        "b" => (-1, true),
        _ => return Err(Error),
    };
    let index = (base + offset).rem_euclid(12) as usize;
    Ok((index, flat))
}

/// Converts an interval code into a number of semitones.
fn interval_steps(code: char) -> Result<usize, Error> {
    match code {
        'm' => Ok(1), // minor second (half step)
        'M' => Ok(2), // major second (whole step)
        'A' => Ok(3), // augmented second (three half steps)
        _ => Err(Error),
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let (start, flat_accidental) = parse_tonic(tonic)?;
        let steps = intervals
            .chars()
            .map(interval_steps)
            .collect::<Result<Vec<usize>, Error>>()?;
        let use_flats = flat_accidental || FLAT_TONICS.iter().any(|&t| t == tonic);

        Ok(Scale {
            start,
            intervals: steps,
            use_flats,
        })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        let names: &[&str; 12] = if self.use_flats {
            &FLAT_NAMES
        } else {
            &SHARP_NAMES
        };

        let mut current = self.start;
        let mut result = Vec::with_capacity(self.intervals.len());
        for &step in &self.intervals {
            result.push(names[current].to_string());
            current = (current + step) % 12;
        }
        result
    }
}
