                        attrs
                            .iter()
                            .map(|(k, v)| (k.to_string(), v.to_string())),
                    );
                    self
                }

                pub fn get_attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }
            }
