        pub mod edge {
            use std::collections::HashMap;

            /// A directed connection between two nodes, identified by source and destination names.
            #[derive(Clone, Debug, Default, PartialEq, Eq)]
            pub struct Edge {
                pub src: String,
                pub dst: String,
                pub attrs: HashMap<String, String>,
            }

