                            .iter()
                            .map(|(k, v)| (k.to_string(), v.to_string())),
                    );
                    self
                }

                pub fn get_attr(&self, key: &str) -> Option<&str> {
                    self.attrs.get(key).map(String::as_str)
                }
            }
        }
    }

    pub use graph_items::edge::Edge;
    pub use graph_items::node::Node;

    #[derive(Clone, Debug, Default, PartialEq, Eq)]
    pub struct Graph {
        pub nodes: Vec<Node>,
        pub edges: Vec<Edge>,
        pub attrs: HashMap<String, String>,
    }

    impl Graph {
        pub fn new() -> Self {
            Graph {
                nodes: Vec::new(),
                edges: Vec::new(),
                attrs: HashMap::new(),
            }
        }

        /// Adds nodes to the graph. A node whose name already exists has its attributes merged in.
        pub fn with_nodes(mut self, nodes: &[Node]) -> Self {
            for node in nodes {
                match self.nodes.iter().position(|n| n.name == node.name) {
                    Some(index) => self.nodes[index].attrs.extend(node.attrs.clone()),
                    None => self.nodes.push(node.clone()),
                }
            }
            self
        }

        pub fn with_edges(mut self, edges: &[Edge]) -> Self {
            self.edges.extend_from_slice(edges);
            self
        }

        pub fn with_attrs(mut self, attrs: &[(&str, &str)]) -> Self {
            self.attrs.extend(
                attrs
                    .iter()
                    .map(|(k, v)| (k.to_string(), v.to_string())),
            );
            self
        }

        pub fn get_node(&self, name: &str) -> Option<&Node> {
            self.nodes.iter().find(|node| node.name == name)
        }
    }
