#[derive(Debug)]
pub struct Error;

pub struct Scale {
    notes: Vec<String>,
}

const SHARP_NAMES: [&str; 12] = [
    "A", "A#", "B", "C", "C#", "D", "D#", "E", "F", "F#", "G", "G#",
];

const FLAT_NAMES: [&str; 12] = [
    "A", "Bb", "B", "C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab",
];

/// Semitone index (0 = A) for a tonic name, if valid.
fn tonic_index(tonic: &str) -> Option<usize> {
    let mut chars = tonic.chars();
    let letter = chars.next()?.to_ascii_uppercase();
    let accidental = chars.next();
    if chars.next().is_some() {
        return None;
    }
    // Semitone offset of the natural note relative to A.
    let base: i32 = match letter {
        'A' => 0,
        'B' => 2,
        'C' => 3,
        'D' => 5,
        'E' => 7,
        'F' => 8,
        'G' => 10,
        _ => return None,
    };
    let offset = match accidental {
        None => 0,
        Some('#') => 1,
        Some('b') => -1,
        Some(_) => return None,
    };
    Some((base + offset).rem_euclid(12) as usize)
}

/// Whether a tonic is conventionally spelled with flats.
fn uses_flats(tonic: &str) -> bool {
    matches!(
        tonic,
        "F" | "Bb" | "Eb" | "Ab" | "Db" | "Gb" | "d" | "g" | "c" | "f" | "bb" | "eb"
    )
}

fn interval_steps(interval: char) -> Option<usize> {
    match interval {
        'm' => Some(1),
        'M' => Some(2),
        'A' => Some(3),
        _ => None,
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let start = tonic_index(tonic).ok_or(Error)?;
        let names: &[&str; 12] = if uses_flats(tonic) {
            &FLAT_NAMES
        } else {
            &SHARP_NAMES
        };

        let mut notes = Vec::new();
        let mut current = start;
        notes.push(names[current].to_string());
        for interval in intervals.chars() {
            let steps = interval_steps(interval).ok_or(Error)?;
            current = (current + steps) % 12;
            notes.push(names[current].to_string());
        }
        // The final interval in a diatonic scale returns to the tonic, which
        // is already emitted as the first note; drop a trailing duplicate.
        if notes.len() > 1 && current == start {
            notes.pop();
        }
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        Scale::new(tonic, "mmmmmmmmmmm")
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
}
