/// Returns true if the tonic should be spelled with flats.
fn uses_flats(tonic: &str) -> bool {
    let mut chars = tonic.chars();
    let first = chars.next();
    let rest = chars.as_str();

    if rest == "b" {
        return true;
    }
    if rest.is_empty() {
        match first {
            Some('F') | Some('f') => return true,
            Some('d') | Some('g') | Some('c') => return true,
            _ => {}
        }
    }
    false
}

/// Normalizes the tonic so the note name starts with an uppercase letter.
fn normalize(tonic: &str) -> String {
    let mut chars = tonic.chars();
    match chars.next() {
        Some(first) => {
            let mut s: String = first.to_uppercase().collect();
            s.push_str(chars.as_str());
            s
        }
        None => String::new(),
    }
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let table: &[&str; 12] = if uses_flats(tonic) { &FLATS } else { &SHARPS };
        let name = normalize(tonic);
        let mut idx = table
            .iter()
            .position(|&n| n == name)
            .ok_or(Error)?;

        let mut notes = Vec::new();
        for ch in intervals.chars() {
            let step = match ch {
                'm' => 1,
                'M' => 2,
                'A' => 3,
                _ => return Err(Error),
            };
            notes.push(table[idx].to_string());
            idx = (idx + step) % 12;
        }

        Ok(Scale { notes })
    }

