const FLAT_TONICS: [&str; 12] = [
    "F", "Bb", "Eb", "Ab", "Db", "Gb", "d", "g", "c", "f", "bb", "eb",
];

pub struct Scale {
    notes: Vec<String>,
}

/// Builds the list of notes from a tonic and a sequence of half-step counts.
/// One note is produced per step; the final step's destination is not included.
fn build(tonic: &str, steps: &[usize]) -> Result<Vec<String>, Error> {
    let uses_flats = FLAT_TONICS.contains(&tonic);
    let table = if uses_flats { FLAT_NOTES } else { SHARP_NOTES };

    // Normalize the first letter to uppercase so that minor tonics such as
    // "d" or "bb" match the note names in the table.
    let mut chars = tonic.chars();
    let first = chars.next().ok_or(Error)?.to_ascii_uppercase();
    let normalized = format!("{}{}", first, chars.as_str());

    let mut idx = table
        .iter()
        .position(|n| *n == normalized)
        .ok_or(Error)?;

    let mut notes = Vec::with_capacity(steps.len());
    for &step in steps {
        notes.push(table[idx].to_string());
        idx = (idx + step) % 12;
    }
    Ok(notes)
}

impl Scale {
    pub fn new(tonic: &str, intervals: &str) -> Result<Scale, Error> {
        let steps = intervals
            .chars()
            .map(|c| match c {
                'm' => Ok(1usize),
                'M' => Ok(2usize),
                'A' => Ok(3usize),
                _ => Err(Error),
            })
            .collect::<Result<Vec<usize>, Error>>()?;

        let notes = build(tonic, &steps)?;
        Ok(Scale { notes })
    }

    pub fn chromatic(tonic: &str) -> Result<Scale, Error> {
        let steps = vec![1usize; 12];
        let notes = build(tonic, &steps)?;
        Ok(Scale { notes })
    }

    pub fn enumerate(&self) -> Vec<String> {
        self.notes.clone()
    }
