// Turns a function that follows the Node-style callback convention
// (the callback is the last argument and receives `(error, data)`)
// into a function that returns a Promise instead.
export const promisify = (fn) =>
  function promisified(...args) {
    return new Promise((resolve, reject) => {
      fn.call(this, ...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
  };

// Resolves with an array of all values (in input order) once every promise
// has fulfilled. Rejects as soon as any promise rejects.
export const all = (promises) =>
  new Promise((resolve, reject) => {
    const items = Array.from(promises);
    const results = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      resolve(results);
      return;
    }

    items.forEach((item, index) => {
      Promise.resolve(item).then((value) => {
        results[index] = value;
        pending -= 1;

        if (pending === 0) {
          resolve(results);
        }
      }, reject);
    });
  });

// Resolves with an array of outcome objects, in input order, once every
// promise has settled. Never rejects.
export const allSettled = (promises) =>
  new Promise((resolve) => {
    const items = Array.from(promises);
    const results = new Array(items.length);
    let pending = items.length;

    if (pending === 0) {
      resolve(results);
      return;
    }

    const record = (index, outcome) => {
      results[index] = outcome;
      pending -= 1;

      if (pending === 0) {
        resolve(results);
      }
    };

    items.forEach((item, index) => {
      Promise.resolve(item).then(
        (value) => record(index, { status: 'fulfilled', value }),
        (reason) => record(index, { status: 'rejected', reason })
      );
    });
  });

// Settles with the outcome of whichever promise settles first.
// An empty input never settles (same as the built-in Promise.race).
export const race = (promises) =>
  new Promise((resolve, reject) => {
    Array.from(promises).forEach((item) => {
      Promise.resolve(item).then(resolve, reject);
    });
  });

// Resolves with the first value that fulfils. If every promise rejects
// (or the input is empty), rejects with an AggregateError whose `errors`
// hold the rejection reasons in input order.
export const any = (promises) =>
  new Promise((resolve, reject) => {
    const items = Array.from(promises);
    const errors = new Array(items.length);
    let pending = items.length;

    const rejectAll = () => {
      reject(new AggregateError(errors, 'All promises were rejected'));
    };

    if (pending === 0) {
      rejectAll();
      return;
    }

    items.forEach((item, index) => {
      Promise.resolve(item).then(resolve, (reason) => {
        errors[index] = reason;
        pending -= 1;

        if (pending === 0) {
          rejectAll();
        }
      });
    });
  });
```

