    combined = []
    i = 0
    while i < len(tokens):
        if i + 1 < len(tokens):
            pair = f"{tokens[i]} {tokens[i + 1]}"
            if pair in ("multiplied by", "divided by"):
                combined.append(pair)
                i += 2
                continue
        combined.append(tokens[i])
        i += 1

    tokens = combined

    # A single number is a valid question.
    first = _parse_int(tokens[0])
    if first is None:
        # Determine whether the first token looks like an unknown operation
        # (a word) versus malformed input.
        if tokens[0].lstrip("-").isalpha() or tokens[0] in ("multiplied by", "divided by"):
            raise ValueError("syntax error")
        raise ValueError("syntax error")

    result = first
    i = 1
    if len(tokens) == 1:
        return result

    while i < len(tokens):
        op_token = tokens[i]
        if i + 1 >= len(tokens):
            raise ValueError("syntax error")

        operand = _parse_int(tokens[i + 1])
        if operand is None:
            raise ValueError("syntax error")

        if op_token == "plus":
            result = result + operand
        elif op_token == "minus":
            result = result - operand
        elif op_token == "multiplied by":
            result = result * operand
        elif op_token == "divided by":
            if operand == 0:
                raise ValueError("division by zero")
            result = int(result / operand)
        else:
            if _parse_int(op_token) is not None:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")

        i += 2

    return result
