    words = body.split()
    tokens = []
    i = 0
    while i < len(words):
        word = words[i]
        if word in ("multiplied", "divided") and i + 1 < len(words) and words[i + 1] == "by":
            tokens.append(f"{word} by")
            i += 2
        else:
            tokens.append(word)
            i += 1
    return tokens


