    if NUMBER_PATTERN.fullmatch(token):
        return int(token)
    return None


def answer(question):
    text = question.strip()
    if not text.startswith(PREFIX):
        raise ValueError("unknown operation")

    body = text[len(PREFIX):].strip()
    if body.endswith("?"):
        body = body[:-1]

    tokens = _tokenize(body)
    if not tokens:
        raise ValueError("syntax error")

    # The first token must be a number.
    result = _to_number(tokens[0])
    if result is None:
        if tokens[0] in OPERATIONS:
            raise ValueError("syntax error")
        raise ValueError("unknown operation")

    # Remaining tokens must come in (operation, number) pairs.
    i = 1
    while i < len(tokens):
        op_token = tokens[i]
        if op_token not in OPERATIONS:
            if _to_number(op_token) is not None:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")

        if i + 1 >= len(tokens):
            raise ValueError("syntax error")

        operand_token = tokens[i + 1]
        operand = _to_number(operand_token)
        if operand is None:
            if operand_token in OPERATIONS:
                raise ValueError("syntax error")
            raise ValueError("unknown operation")

        result = OPERATIONS[op_token](result, operand)
        i += 2

    return result
