        try:
            return int(token)
        except ValueError:
            raise ValueError("syntax error")

    # A lone number is a valid question.
    if len(merged) == 1:
        return parse_number(merged[0])

    # Single-token words that aren't numbers or known operations.
    result = parse_number(merged[0])
    i = 1
    while i < len(merged):
        op_token = merged[i]
        if i + 1 >= len(merged):
            raise ValueError("syntax error")
        if op_token not in OPERATIONS:
            # Distinguish unknown operations from malformed input.
            if op_token.lstrip("-").isdigit():
                raise ValueError("syntax error")
            raise ValueError("unknown operation")
        operand = parse_number(merged[i + 1])
        if op_token == "divided by":
            result = _divide(result, operand)
        else:
            result = OPERATIONS[op_token](result, operand)
